from lib import *
S = SS('w98')
steps = [
    step("一次完整的 SMTP 对话(明文,本机 aiosmtpd 服务器)。服务器先发 “220 mail.w98.test Python SMTP 1.4.6”;客户端 EHLO,服务器用多行答复列出扩展:前面各行 “250-”,最后一行 “250 ”(横线表示后面还有,空格表示最后一行)——SIZE 2000、8BITMIME、SMTPUTF8、STARTTLS、HELP。然后 MAIL FROM:<envelope-sender@w98.test>(250 OK)、RCPT TO:<bob@w98.test>(250 OK)、RCPT TO:<hidden-bcc@w98.test>(250 OK)、DATA(354 End data with <CR><LF>.<CR><LF>),发出信件,以 CRLF.CRLF 结束,服务器回 “250 OK: queued as w98-1”,QUIT(221 Bye)。每个答复的前三位是状态码,命令和答复一问一答。 信封 ≠ 信件头。服务器收到的信封:MAIL FROM = envelope-sender@w98.test,RCPT TO = [bob@w98.test, hidden-bcc@w98.test]。但信件头里的 To 只写了 bob@w98.test,From 是 \"Alice\" <alice@example.org>。信封里有 hidden-bcc 而信件头里没有——这就是 Bcc 的实现原理(密送收件人只在信封里)。信件头里的 From 与信封里的 MAIL FROM 完全不同,SMTP 本身不核对两者——这也是伪造发件人的基础,SPF / DKIM / DMARC 都是后来补上的核对机制。点转义:正文里有一行以点开头 “.dot-line”,线上写成 “..dot-line”(线上字节 b'First line.\\r\\n..dot-line\\r\\nLast ' 可以看到),服务器还原后收到的是 “.dot-line”;不转义的话,一行单独的 “.” 会被误认为信件结束。", t=tl(S(1)), mark=lidx(S(1), 'S: 220 mail.w98.test', 'C: MAIL FROM', 'C: DATA', '服务器收到的信封', '点转义'), done=lidx(S(1), 'C: EHLO', 'S: 354', 'S: 221', '信件头里的 From', '线上字节'), kv=KV([['问候', '220 mail.w98.test'], ['EHLO 扩展', 'SIZE、8BITMIME、SMTPUTF8、STARTTLS、HELP'], ['信封', 'MAIL FROM envelope-sender@;RCPT TO bob@ + hidden-bcc@'], ['信件头', 'From alice@example.org;To bob@']], ['信封'])),
    step("错误答复与重试:状态码第一位分类——2 成功、3 继续、4 临时失败(稍后重试)、5 永久失败。本机服务器对特定收件人返回不同的码:RCPT TO:<blocked@…> → 550 5.7.1 Relaying denied(永久失败,发送方应该退信);RCPT TO:<later@…> → 450 4.2.0 Greylisted, try again later(临时失败,灰名单,稍后重试);RCPT TO:<ok@…> → 250 OK;FOOBAR → 500 Error: command \"FOOBAR\" not recognized;RSET → 250 OK;紧接着 DATA → 503 Error: need RCPT command(命令顺序不对)。带 “5.7.1” 这样的三段数字是增强状态码,比三位码更精确。", t=tl(S(2)), mark=lidx(S(2), 'S: 550', 'S: 450', 'S: 500', 'S: 503'), done=lidx(S(2), 'C: RCPT TO:<ok', 'C: RSET'), kv=KV([['550', '永久失败,退信'], ['450', '临时失败,稍后重试'], ['500', '未知命令'], ['503', '命令顺序不对']], ['450'])),
    step("SIZE 限制:服务器在 EHLO 里宣告 SIZE 2000。声明过大(MAIL FROM:<…> SIZE=5000)→ 立刻 552 Error: message size exceeds fixed maximum message size,在发正文之前就被拒绝。不声明而直接发过大的正文(约 3000 字节,每行 98 字节)→ 要等到 DATA 结束才被拒绝:552 Error: Too much mail data。所以声明 SIZE 可以省掉白发的字节。(我第一次把 3000 字节写成一行,先碰到的是 “500 Line too long”——SMTP 单行最多 1000 字节。)", t=tl(S(3)), mark=lidx(S(3), 'SIZE=5000', 'S: 552 Error: message size', 'S: 552 Error: Too much'), done=lidx(S(3), 'S: 250-SIZE'), kv=KV([['声明 SIZE=5000', '立刻 552,正文不用发'], ['不声明直接发 3000 字节', 'DATA 结束后 552 Too much mail data'], ['单行限制', '1000 字节(500 Line too long)']], ['声明 SIZE=5000'])),
    step("STARTTLS 与真实服务器。先明文 EHLO,服务器宣告 STARTTLS;客户端发 STARTTLS,服务器回 “220 Ready to start TLS”,同一个 TCP 连接升级成 TLS;升级后再 EHLO,答复里不再宣告 STARTTLS(已经加密了)。抓 lo0:整个连接的字节里能找到升级前的明文 “EHLO client.w98.test”,能找到明文 “STARTTLS” 命令,但找不到升级后才发的 “secret-sender@w98.test”——已加密。弱点:升级前全是明文,路径上的设备可以把 EHLO 答复里的 “250 STARTTLS” 删掉(降级攻击),“尽量用 TLS”的发送方就会继续明文发信。", t=tl(S(4)), mark=lidx(S(4), '升级前 EHLO', '整个连接的字节里'), done=lidx(S(4), '注意 STARTTLS 的弱点'), kv=KV([['升级前', '明文:EHLO、STARTTLS 命令'], ['升级后', '密文:找不到 secret-sender@'], ['弱点', '降级攻击:删掉 250 STARTTLS']], ['弱点'])),
    step("真实服务器(只做问候和 EHLO,没有发信):gmail-smtp-in.l.google.com 问候 996 ms,扩展 SIZE、8BITMIME、STARTTLS、ENHANCEDSTATUSCODES、PIPELINING、CHUNKING、SMTPUTF8;mx1.qq.com 问候 146 ms,扩展 STARTTLS、8BITMIME、SMTPUTF8、SIZE;smtp.163.com 问候 90 ms,扩展 AUTH、AUTH=LOGIN、coremail、STARTTLS、ID、8BITMIME。三家都宣告了 STARTTLS。", t=tl(S(5)), mark=lidx(S(5), 'gmail-smtp-in.l.google.com', 'mx1.qq.com', 'smtp.163.com'), done=lidx(S(5), 'gmail-smtp-in.l.google.com'), b=bars([['Gmail 问候', 996, '996 ms'], ['QQ 问候', 146, '146 ms'], ['163 问候', 90, '90 ms']], 996, mark=[0], done=[1, 2]), kv=KV([['Gmail', 'SIZE、8BITMIME、STARTTLS、ENHANCEDSTATUSCODES、PIPELINING、CHUNKING、SMTPUTF8'], ['QQ', 'STARTTLS、8BITMIME、SMTPUTF8、SIZE'], ['163', 'AUTH、AUTH=LOGIN、coremail、STARTTLS、ID、8BITMIME']], ['Gmail']))
]
A = mkartw('w98', 98, '网络协议,SMTP,邮件,STARTTLS,信封,Bcc,状态码,真实验证,动画演示',
    '实测 SMTP:本机 aiosmtpd 上逐行看 EHLO 多行答复、信封(MAIL FROM / RCPT TO)与信件头不同(Bcc 原理、发件人可伪造)、点转义;550 / 450 / 500 / 503 / 552 各是什么;STARTTLS 升级前明文升级后密文;Gmail、QQ、163 的 25 端口都宣告 STARTTLS。',
    '一封邮件在服务器之间怎么传?答案是一场 40 年历史的文本对话:HELO、MAIL FROM、RCPT TO、DATA。这篇在本机起一个 SMTP 服务器,逐行看这场对话、信封和信件头为什么不一样、错误码怎么分类、STARTTLS 怎么把明文连接升级成加密,最后到真实的 Gmail、QQ、163 邮件服务器上只做问候和 EHLO。',
    [('2 个收件人 vs 1 个', '信封里有 bob 和 hidden-bcc 两个收件人,而信件头 To 里只有 bob:Bcc 的原理'), ('552 两种', '声明 SIZE=5000 在 MAIL FROM 阶段就被拒绝;不声明直接发大正文要到 DATA 结束才被拒绝'), ('3 / 3', 'Gmail、QQ、163 三台真实邮件服务器宣告 STARTTLS 的个数')],
    [('一场对话', '<p>220 → EHLO(多行 250)→ MAIL FROM → RCPT TO → DATA(354)→ 正文以 CRLF.CRLF 结束 → 250 → QUIT。</p>'),
     ('信封与信件头', '<p>收件人和发件人都有两套:信封给传输用,信件头给人看,SMTP 不核对它们。</p>'),
     ('状态码', '<p>2 成功、4 临时失败、5 永久失败;增强状态码 5.7.1 更精确。</p>'),
     ('SIZE', '<p>EHLO 宣告上限,MAIL FROM 带 SIZE 可以提前被拒绝。</p>'),
     ('STARTTLS 与真实服务器', '<p>把已有的明文连接升级成 TLS,升级前一切明文,存在降级攻击;Gmail、QQ、163 都宣告 STARTTLS。</p>')],
    steps,
    [ENV_W + '。前四节在本机 lo0 上,服务器是 aiosmtpd(Python),STARTTLS 用临时生成的自签名证书(客户端不校验);第五节对 Gmail、QQ、163 的 25 端口只收问候和 EHLO 的答复,不使用 MAIL FROM,不发任何邮件',
     '没有验证:AUTH(认证,163 宣告了 AUTH LOGIN);SPF、DKIM、DMARC;MTA-STS 和 DANE 对 STARTTLS 降级的防护;端口 465(隐式 TLS)与 587(提交端口);邮件队列、重试间隔和退信格式(DSN);PIPELINING 与 CHUNKING 的具体行为;从本机真实发出邮件(没有做)'],
    'SMTP')
